package com.sincerelyuq.vastlands.worldgen;

import com.sincerelyuq.vastlands.Vastlands;
import com.sincerelyuq.vastlands.worldgen.context.GenerationContext;
import java.util.Optional;
import net.minecraft.server.level.ServerLevel;
import net.neoforged.neoforge.event.level.LevelEvent;

/**
 * Startup checks for levels generated by {@link VastlandsChunkGenerator}. A mismatch between the
 * dimension type and the noise settings does not crash vanilla; it silently clips the terrain, so it
 * is reported here instead.
 */
public final class WorldgenDiagnostics {
    private WorldgenDiagnostics() {
    }

    public static void onLevelLoad(LevelEvent.Load event) {
        if (!(event.getLevel() instanceof ServerLevel level)
                || !(level.getChunkSource().getGenerator() instanceof VastlandsChunkGenerator generator)) {
            return;
        }

        String dimension = level.dimension().location().toString();
        int levelMinY = level.getMinY();
        int levelMaxY = level.getMaxY();
        int noiseMinY = generator.getMinY();
        int noiseMaxY = noiseMinY + generator.getGenDepth() - 1;

        if (levelMinY != noiseMinY || levelMaxY != noiseMaxY) {
            Vastlands.LOGGER.error(
                    "Vastlands: {} builds in Y {}..{} but its noise settings generate Y {}..{}; terrain outside the overlap will be missing",
                    dimension, levelMinY, levelMaxY, noiseMinY, noiseMaxY);
        }

        Optional<GenerationContext> context = GenerationContext.of(level);
        if (context.isPresent()) {
            Vastlands.LOGGER.info("Vastlands: generating {} in Y {}..{} ({})",
                    dimension, levelMinY, levelMaxY, context.get().systems().describe());
        } else {
            Vastlands.LOGGER.warn("Vastlands: {} uses the Vastlands generator, but its noise settings contain no Vastlands stage", dimension);
        }
    }
}
